*******************************************************************************
* v3char.asm -- video3's character mode on the host emulator.  GENERATED by
* bench/mkv3char.py; edit the generator.
*
*   sh video3/bench/run-v3char.sh
*
* plan 2.2 and 3: the map is FOUR bytes a cell - the code at +0, the attribute
* at +2, and +1/+3 never read - and the attribute is the HIGH
* eight bits of the LUT address, so a cell's colours are a sub-palette rather
* than a bank.  A wrong ATTR path renders the right shapes in the wrong
* colours - which a pixel-exact model catches and a register trace does not.
*
* The map goes in with WADV b2 set, the card's step-by-two write (plan 2.5),
* which is what makes a cell TWO VDATA writes rather than four.
*******************************************************************************

VCTRL   EQU     $FF60
WPTR0   EQU     $FF68
WPTR1   EQU     $FF69
WPTR2   EQU     $FF6A
WADV    EQU     $FF6B
VDATA   EQU     $FF6C
PIDXL   EQU     $FF6E
PIDXH   EQU     $FF6F
PDATL   EQU     $FF70
PDATH   EQU     $FF71
TILEBAS EQU     $FF78
MAPBAS  EQU     $FF79
SIMPORT EQU     $FF2F
VSTAT   EQU     $FF6D
SPRX    EQU     $FF7A
SPRY    EQU     $FF7B
SPRH    EQU     $FF7C
MKV     EQU     $C20A           machine.c records this with every frame

NGLYPH  EQU     8
NROWS   EQU     64
TBASE   EQU     16384

        ORG     $8000
        FCC     "6309"
        JMP     start

        SETDP   $FF
start   orcc    #$50
        lds     #$E000
        lda     #$FF
        tfr     a,dp
        clr     <VCTRL          display off, bitmap, WMODE 00 direct
        clr     <WADV
        lda     #1
        sta     <TILEBAS
        lda     #2
        sta     <MAPBAS

* --- 256 sub-palettes, entries 0 and 1.  PIDX is 16 bits and increments
*     after PDATH, so one index write covers a pair.
        ldx     #paltab
        clrb
pal1    stb     <PIDXH
        clr     <PIDXL
        lda     ,x+
        sta     <PDATL
        lda     ,x+
        sta     <PDATH
        lda     ,x+
        sta     <PDATL
        lda     ,x+
        sta     <PDATH
        incb
        bne     pal1

* --- the glyph bank: one byte a pixel, at TBASE + code * 64
        ldx     #glyphtab
        ldb     #NGLYPH
gl1     pshs    b
        lda     ,x+
        clrb
        lsra
        rorb
        lsra
        rorb                    D = code * 64
        addd    #TBASE
        stb     <WPTR0
        sta     <WPTR1
        clr     <WPTR2
        ldb     #64
gl2     lda     ,x+
        sta     <VDATA
        decb
        bne     gl2
        puls    b
        decb
        bne     gl1

* --- the map: four bytes a cell, one VRAM row a cell row, in TWO PASSES and
*     both of them with WADV b2 set - the card's step-by-two write (plan 2.5).
*     ⭐ Pass one starts at an ODD address, so stepping by two fills +1 and +3
*     of every cell with a decoy code and a decoy attribute the card must
*     never read.  Pass two starts at the even one and writes the cell itself:
*     the code into lane 0, the attribute into lane 2, two stores a character.
*     A card that reads the odd lanes, or a pointer that steps by one, paints
*     the decoy instead of the cell.
        lda     #$04
        sta     <WADV           b2: step by two
        ldx     #maptab
        clra
        ldb     #NROWS
mr1     pshs    a,b
        lda     #2
        sta     <WPTR2
        lda     ,s
        lsla
        lsla                    row * 4 -> WPTR1, a 1024-byte stride
        sta     <WPTR1
        lda     #1
        sta     <WPTR0          the ODD lane of cell 0
        ldy     #80
mr0     lda     #$B0
        sta     <VDATA          lane 1: a decoy code
        lda     #$77
        sta     <VDATA          lane 3: a decoy attribute
        leay    -1,y
        bne     mr0
        lda     ,s
        lsla
        lsla
        sta     <WPTR1
        clr     <WPTR0          and back to the even lane of cell 0
        ldy     #80
mr2     lda     ,x+
        sta     <VDATA          lane 0: the code
        lda     ,x+
        sta     <VDATA          lane 2: the attribute
        leay    -1,y
        bne     mr2
        puls    a,b
        inca
        decb
        bne     mr1
        clr     <WADV           ⛔ b2 off: everything below steps by one

* --- character mode, every VMODE in turn.  Each is set, allowed to settle -
*     graphics.md 6.2 latches the family at FRAME END - and only then marked at
*     $C20A, so no frame is judged against a geometry it was not drawn in.
        lda     #$A0
        sta     SIMPORT
        ldd     #$FFFF
        std     MKV
        lda     #$84          display on, MODE 01, VMODE 00 - 80x25, 449-line, doubled
        sta     <VCTRL
        lbsr    wait3
        ldd     #0
        std     MKV
        lbsr    wait3
        ldd     #$FFFF
        std     MKV
        lda     #$85          display on, MODE 01, VMODE 01 - 80x30, 525-line, doubled
        sta     <VCTRL
        lbsr    wait3
        ldd     #1
        std     MKV
        lbsr    wait3
        ldd     #$FFFF
        std     MKV
        lda     #$86          display on, MODE 01, VMODE 10 - 80x50, 449-line, progressive
        sta     <VCTRL
        lbsr    wait3
        ldd     #2
        std     MKV
        lbsr    wait3
        ldd     #$FFFF
        std     MKV
        lda     #$87          display on, MODE 01, VMODE 11 - 80x60, 525-line, progressive
        sta     <VCTRL
        lbsr    wait3
        ldd     #3
        std     MKV
        lbsr    wait3
        ldd     #$FFFF
        std     MKV
* --- ⭐ plan 7's negative half.  Arm the sprite, PROVE the register took the
*     enable - otherwise the test asserts nothing - and require that character
*     mode shows no trace of it.  bench/v3sprite is the positive control.
*     The shape is in VRAM at MAPBASE's top 64 bytes (plan 7), written with
*     ordinary VDATA writes: eight rows of $FF,0,0,0 - columns 0-7 opaque in
*     sub-palette 1, an 8 x 8 - and the other eight rows left zero.
        lda     #$02
        sta     <WPTR2
        lda     #$FF
        sta     <WPTR1
        lda     #$C0
        sta     <WPTR0
        ldb     #8
sp1     lda     #$FF
        sta     <VDATA          low plane, columns 0-7
        clr     <VDATA
        clr     <VDATA
        clr     <VDATA
        decb
        bne     sp1
        ldb     #32
sp0     clr     <VDATA          rows 8-15 transparent
        decb
        bne     sp0
        lda     #$20
        sta     <SPRX           x = 32
        lda     #$08
        sta     <SPRY           y = 8, so cell (1,4) - its attribute is $2A
        lda     #$80
        sta     <SPRH           b7 enable
        lda     <SPRH
        cmpa    #$80
        beq     sp2
        lda     #$E1            the register refused the enable: fail loudly
        sta     SIMPORT
sp2     lda     #$84            display on, MODE 01, VMODE 00, sprite ARMED
        sta     <VCTRL
        lbsr    wait3
        ldd     #4
        std     MKV
        lbsr    wait3
        ldd     #$FFFF
        std     MKV
        lda     #$AF
        sta     SIMPORT
done    bra     done

wait3   pshs    a,b
        ldb     #3
w1      lda     <VSTAT
        bita    #$40
        bne     w1
w2      lda     <VSTAT
        bita    #$40
        beq     w2
        decb
        bne     w1
        puls    a,b,pc

